  <div class="section-title">Exercises</div>
  <div class="form-group">
    <label>Quick Add</label>
    <div class="quick-exercises" id="quick-exercises"></div>
  </div>

  <div class="form-row" style="margin-bottom:14px;">
    <div class="form-group" style="flex:3">
      <input type="text" id="new-exercise-name" placeholder="Custom exercise name..." />
    </div>
    <div class="form-group" style="flex:1">
      <button class="btn btn-secondary" onclick="addExercise()" style="height:100%;padding:0;">+ Add</button>
    </div>
  </div>

  <div class="exercise-list" id="exercise-list"></div>

  <div class="form-group">
    <label>Notes (optional)</label>
    <textarea id="workout-notes" placeholder="How did it feel? Energy level?"></textarea>
  </div>

  <button class="btn btn-primary" onclick="saveWorkout()">💾 Save Workout</button>
</div>

<!-- HISTORY TAB -->
<div class="section" id="sec-history">
  <div class="section-title">📋 History</div>
  <div class="search-bar">
    <input type="text" id="search-input" placeholder="Search workouts..." oninput="renderHistory()" />
  </div>
  <div id="history-list"></div>
</div>

<!-- STATS TAB -->
<div class="section" id="sec-stats">
  <div class="section-title">📊 Stats</div>
  <div class="stat-grid" id="stat-grid"></div>

  <div class="section-title">📅 This Month</div>
  <div class="month-nav">
    <button onclick="changeMonth(-1)">◀</button>
    <span class="month-label" id="month-label"></span>
    <button onclick="changeMonth(1)">▶</button>
  </div>
  <div class="calendar-grid" id="calendar-grid"></div>

  <div class="chart-container">
    <div class="chart-title">Workouts per Week (last 8 weeks)</div>
    <div class="bar-chart" id="week-chart"></div>
  </div>

  <div class="section-title">🏆 Personal Records</div>
  <div class="card" id="pr-list">
    <div class="empty-state"><p>No data yet</p></div>
  </div>
</div>

<!-- TIMER TAB -->
<div class="section" id="sec-timer">
  <div class="section-title">⏱️ Rest Timer</div>
  <div class="card">
    <div class="timer-display">
      <div class="timer-time" id="timer-time">1:30</div>
      <div class="timer-label">Rest between sets</div>
      <div class="timer-presets">
        <button class="timer-preset" onclick="setTimer(30)">0:30</button>
        <button class="timer-preset" onclick="setTimer(60)">1:00</button>
        <button class="timer-preset active" onclick="setTimer(90)">1:30</button>
        <button class="timer-preset" onclick="setTimer(120)">2:00</button>
        <button class="timer-preset" onclick="setTimer(180)">3:00</button>
        <button class="timer-preset" onclick="setTimer(300)">5:00</button>
      </div>
      <div class="timer-controls">
        <button class="btn btn-primary btn-sm" id="timer-start" onclick="toggleTimer()">▶ Start</button>
        <button class="btn btn-secondary btn-sm" onclick="resetTimer()">↺ Reset</button>
      </div>
    </div>
  </div>

  <div class="section-title" style="margin-top:20px">🧮 1RM Calculator</div>
  <div class="card">
    <div class="form-row">
      <div class="form-group">
        <label>Weight</label>
        <input type="number" id="orm-weight" placeholder="lbs" oninput="calc1RM()" />
      </div>
      <div class="form-group">
        <label>Reps</label>
        <input type="number" id="orm-reps" placeholder="reps" oninput="calc1RM()" />
      </div>
    </div>
    <div id="orm-result" style="text-align:center; padding:10px; color:var(--text-dim); font-size:0.9rem;">
      Enter weight and reps to estimate your one-rep max
    </div>
  </div>
</div>

<!-- TAB BAR -->
<div class="tab-bar">
  <button class="tab-btn active" onclick="switchTab('log')" id="tab-log">
    <span class="icon">🏋️</span> Log
  </button>
  <button class="tab-btn" onclick="switchTab('history')" id="tab-history">
    <span class="icon">📋</span> History
  </button>
  <button class="tab-btn" onclick="switchTab('stats')" id="tab-stats">
    <span class="icon">📊</span> Stats
  </button>
  <button class="tab-btn" onclick="switchTab('timer')" id="tab-timer">
    <span class="icon">⏱️</span> Timer
  </button>
</div>

<script>
  // ─── DATA ──────────────────────────
  let workouts = JSON.parse(localStorage.getItem('workouts') || '[]');
  let currentExercises = [];
  let selectedMuscles = [];
  let editingId = null;
  let calMonth = new Date().getMonth();
  let calYear = new Date().getFullYear();

  const EXERCISES_BY_MUSCLE = {
    Chest: ['Bench Press','Incline Bench','Dumbbell Fly','Push-Ups','Cable Crossover'],
    Back: ['Deadlift','Pull-Ups','Barbell Row','Lat Pulldown','Seated Row'],
    Shoulders: ['Overhead Press','Lateral Raise','Front Raise','Face Pull','Arnold Press'],
    Biceps: ['Barbell Curl','Dumbbell Curl','Hammer Curl','Preacher Curl','Cable Curl'],
    Triceps: ['Tricep Dip','Skull Crusher','Tricep Pushdown','Overhead Extension','Close-Grip Bench'],
    Legs: ['Squat','Leg Press','Lunges','Leg Curl','Leg Extension','Calf Raise','Romanian Deadlift'],
    Core: ['Plank','Crunches','Hanging Leg Raise','Russian Twist','Ab Rollout'],
    Glutes: ['Hip Thrust','Glute Bridge','Bulgarian Split Squat','Cable Kickback','Sumo Deadlift'],
    Cardio: ['Running','Cycling','Rowing','Jump Rope','Stair Climber']
  };

  // ─── INIT ──────────────────────────
  document.getElementById('header-date').textContent = new Date().toLocaleDateString('en-US', { weekday:'long', month:'long', day:'numeric', year:'numeric' });
  document.getElementById('workout-date').valueAsDate = new Date();

  // Muscle tag selection
  document.querySelectorAll('.muscle-tag').forEach(tag => {
    tag.addEventListener('click', () => {
      const m = tag.dataset.muscle;
      tag.classList.toggle('selected');
      selectedMuscles = tag.classList.contains('selected')
        ? [...selectedMuscles, m]
        : selectedMuscles.filter(x => x !== m);
      updateQuickExercises();
    });
  });

  function updateQuickExercises() {
    const el = document.getElementById('quick-exercises');
    if (selectedMuscles.length === 0) {
      el.innerHTML = '<span style="color:var(--text-dim);font-size:0.8rem;">Select muscle groups above for suggestions</span>';
      return;
    }
    const exercises = [];
    selectedMuscles.forEach(m => {
      (EXERCISES_BY_MUSCLE[m] || []).forEach(e => {
        if (!exercises.includes(e)) exercises.push(e);
      });
    });
    el.innerHTML = exercises.map(e =>
      `<button class="quick-ex" onclick="addExercise('${e}')">${e}</button>`
    ).join('');
  }
  updateQuickExercises();

  // ─── EXERCISES ─────────────────────
  function addExercise(name) {
    if (!name) {
      name = document.getElementById('new-exercise-name').value.trim();
      if (!name) return;
      document.getElementById('new-exercise-name').value = '';
    }
    currentExercises.push({ name, sets: [{ weight: '', reps: '' }] });
    renderExercises();
  }

  function removeExercise(i) {
    currentExercises.splice(i, 1);
    renderExercises();
  }

  function addSet(exIdx) {
    currentExercises[exIdx].sets.push({ weight: '', reps: '' });
    renderExercises();
  }

  function removeSet(exIdx, setIdx) {
    if (currentExercises[exIdx].sets.length > 1) {
      currentExercises[exIdx].sets.splice(setIdx, 1);
      renderExercises();
    }
  }

  function updateSet(exIdx, setIdx, field, value) {
    currentExercises[exIdx].sets[setIdx][field] = value;
  }

  function renderExercises() {
    const el = document.getElementById('exercise-list');
    if (currentExercises.length === 0) {
      el.innerHTML = '';
      return;
    }
    el.innerHTML = currentExercises.map((ex, i) => `
      <div class="exercise-item">
        <div class="ex-header">
          <span class="ex-name">${ex.name}</span>
          <button class="remove-ex" onclick="removeExercise(${i})">✕</button>
        </div>
        <div class="set-row" style="margin-bottom:8px;">
          <span></span>
          <span style="flex:1;text-align:center;font-size:0.7rem;color:var(--text-dim);width:auto;">Weight (lbs)</span>
          <span style="flex:1;text-align:center;font-size:0.7rem;color:var(--text-dim);width:auto;">Reps</span>
          <span style="width:24px;"></span>
        </div>
        ${ex.sets.map((s, j) => `
          <div class="set-row">
            <span>Set ${j + 1}</span>
            <input type="number" placeholder="0" value="${s.weight}" onchange="updateSet(${i},${j},'weight',this.value)" />
            <input type="number" placeholder="0" value="${s.reps}" onchange="updateSet(${i},${j},'reps',this.value)" />
            <button class="remove-ex" onclick="removeSet(${i},${j})" style="font-size:0.9rem;padding:0 4px;">${ex.sets.length > 1 ? '✕' : ''}</button>
          </div>
        `).join('')}
        <button class="add-set-btn" onclick="addSet(${i})">+ Add Set</button>
      </div>
    `).join('');
  }

  // ─── SAVE WORKOUT ──────────────────
  function saveWorkout() {
    const name = document.getElementById('workout-name').value.trim();
    const date = document.getElementById('workout-date').value;
    const notes = document.getElementById('workout-notes').value.trim();

    if (!name) return showToast('Please enter a workout name');
    if (currentExercises.length === 0) return showToast('Add at least one exercise');

    const workout = {
      id: editingId || Date.now(),
      name,
      date,
      muscles: [...selectedMuscles],
      exercises: JSON.parse(JSON.stringify(currentExercises)),
      notes,
      createdAt: editingId ? (workouts.find(w => w.id === editingId)?.createdAt || Date.now()) : Date.now()
    };

    if (editingId) {
      const idx = workouts.findIndex(w => w.id === editingId);
      if (idx !== -1) workouts[idx] = workout;
      editingId = null;
    } else {
      workouts.push(workout);
    }

    save();
    clearForm();
    showToast('Workout saved! 💪');
  }

  function clearForm() {
    document.getElementById('workout-name').value = '';
    document.getElementById('workout-date').valueAsDate = new Date();
    document.getElementById('workout-notes').value = '';
    currentExercises = [];
    selectedMuscles = [];
    editingId = null;
    document.querySelectorAll('.muscle-tag').forEach(t => t.classList.remove('selected'));
    renderExercises();
    updateQuickExercises();
  }

  function save() {
    localStorage.setItem('workouts', JSON.stringify(workouts));
  }

  // ─── HISTORY ───────────────────────
  function renderHistory() {
    const el = document.getElementById('history-list');
    const query = document.getElementById('search-input').value.toLowerCase();
    const filtered = workouts
      .filter(w => {
        if (!query) return true;
        return w.name.toLowerCase().includes(query)
          || w.muscles.some(m => m.toLowerCase().includes(query))
          || w.exercises.some(e => e.name.toLowerCase().includes(query));
      })
      .sort((a, b) => new Date(b.date) - new Date(a.date));

    if (filtered.length === 0) {
      el.innerHTML = `<div class="empty-state"><div class="emoji">📭</div><p>${query ? 'No workouts found' : 'No workouts yet. Start logging!'}</p></div>`;
      return;
    }

    el.innerHTML = filtered.map(w => {
      const d = new Date(w.date + 'T00:00:00');
      const dateStr = d.toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric' });
      const totalVolume = w.exercises.reduce((sum, ex) =>
        sum + ex.sets.reduce((s, set) => s + (Number(set.weight) || 0) * (Number(set.reps) || 0), 0), 0);

      return `
        <div class="card workout-card">
          <div class="wk-header">
            <div>
              <div class="wk-title">${w.name}</div>
              <div class="wk-date">${dateStr}</div>
            </div>
            <div style="text-align:right;">
              <div style="font-size:0.75rem;color:var(--text-dim);">Volume</div>
              <div style="font-weight:700;color:var(--green);">${totalVolume > 0 ? totalVolume.toLocaleString() + ' lbs' : '—'}</div>
            </div>
          </div>
          <div class="wk-muscles">
            ${w.muscles.map(m => `<span class="wk-muscle-tag">${m}</span>`).join('')}
          </div>
          <div class="wk-exercises">
            ${w.exercises.map(ex => `
              <div class="wk-ex">
                <div class="wk-ex-name">${ex.name}</div>
                <div class="wk-ex-sets">${ex.sets.map((s, i) => `Set ${i+1}: ${s.weight || '—'}lbs × ${s.reps || '—'}`).join(' &nbsp;|&nbsp; ')}</div>
              </div>
            `).join('')}
          </div>
          ${w.notes ? `<div style="margin-top:10px;font-size:0.82rem;color:var(--text-dim);font-style:italic;">📝 ${w.notes}</div>` : ''}
          <div class="wk-actions">
            <button class="btn btn-secondary btn-sm" onclick="editWorkout(${w.id})">✏️ Edit</button>
            <button class="btn btn-secondary btn-sm" onclick="duplicateWorkout(${w.id})">📋 Repeat</button>
            <button class="btn btn-danger btn-sm" onclick="deleteWorkout(${w.id})">🗑️</button>
          </div>
        </div>
      `;
    }).join('');
  }

  function deleteWorkout(id) {
    if (!confirm('Delete this workout?')) return;
    workouts = workouts.filter(w => w.id !== id);
    save();
    renderHistory();
    showToast('Workout deleted');
  }

  function editWorkout(id) {
    const w = workouts.find(w => w.id === id);
    if (!w) return;
    editingId = id;
    document.getElementById('workout-name').value = w.name;
    document.getElementById('workout-date').value = w.date;
    document.getElementById('workout-notes').value = w.notes || '';
    currentExercises = JSON.parse(JSON.stringify(w.exercises));
    selectedMuscles = [...(w.muscles || [])];
    document.querySelectorAll('.muscle-tag').forEach(t => {
      t.classList.toggle('selected', selectedMuscles.includes(t.dataset.muscle));
    });
    renderExercises();
    updateQuickExercises();
    switchTab('log');
    showToast('Editing workout — make changes and save');
  }

  function duplicateWorkout(id) {
    const w = workouts.find(w => w.id === id);
    if (!w) return;
    editingId = null;
    document.getElementById('workout-name').value = w.name;
    document.getElementById('workout-date').valueAsDate = new Date();
    document.getElementById('workout-notes').value = '';
    currentExercises = JSON.parse(JSON.stringify(w.exercises));
    currentExercises.forEach(ex => ex.sets.forEach(s => { s.weight = ''; s.reps = ''; }));
    selectedMuscles = [...(w.muscles || [])];
    document.querySelectorAll('.muscle-tag').forEach(t => {
      t.classList.toggle('selected', selectedMuscles.includes(t.dataset.muscle));
    });
    renderExercises();
    updateQuickExercises();
    switchTab('log');
    showToast('Template loaded — fill in your sets!');
  }

  // ─── STATS ─────────────────────────
  function renderStats() {
    const now = new Date();
    const thisMonth = workouts.filter(w => {
      const d = new Date(w.date + 'T00:00:00');
      return d.getMonth() === now.getMonth() && d.getFullYear() === now.getFullYear();
    });
    const thisWeek = workouts.filter(w => {
      const d = new Date(w.date + 'T00:00:00');
      const diff = (now - d) / (1000 * 60 * 60 * 24);
      return diff >= 0 && diff < 7;
    });
    const totalVolume = workouts.reduce((sum, w) =>
      sum + w.exercises.reduce((s, ex) =>
        s + ex.sets.reduce((ss, set) => ss + (Number(set.weight) || 0) * (Number(set.reps) || 0), 0), 0), 0);

    // Streak
    let streak = 0;
    const dates = [...new Set(workouts.map(w => w.date))].sort().reverse();
    const today = now.toISOString().split('T')[0];
    let checkDate = new Date(now);
    // If no workout today, start from yesterday
    if (!dates.includes(today)) {
      checkDate.setDate(checkDate.getDate() - 1);
    }
    for (let i = 0; i < 365; i++) {
      const ds = checkDate.toISOString().split('T')[0];
      if (dates.includes(ds)) {
        streak++;
        checkDate.setDate(checkDate.getDate() - 1);
      } else {
        break;
      }
    }

    document.getElementById('stat-grid').innerHTML = `
      <div class="stat-card"><div class="stat-value">${workouts.length}</div><div class="stat-label">Total Workouts</div></div>
      <div class="stat-card"><div class="stat-value">${thisWeek.length}</div><div class="stat-label">This Week</div></div>
      <div class="stat-card"><div class="stat-value">${thisMonth.length}</div><div class="stat-label">This Month</div></div>
      <div class="stat-card"><div class="stat-value">${streak}🔥</div><div class="stat-label">Day Streak</div></div>
    `;

    renderCalendar();
    renderWeekChart();
    renderPRs();
  }

  function renderCalendar() {
    const el = document.getElementById('calendar-grid');
    const label = document.getElementById('month-label');
    const now = new Date();
    const first = new Date(calYear, calMonth, 1);
    const last = new Date(calYear, calMonth + 1, 0);
    label.textContent = first.toLocaleDateString('en-US', { month: 'long', year: 'numeric' });

    const workoutDates = new Set(workouts.map(w => w.date));
    const todayStr = now.toISOString().split('T')[0];

    const days = ['Su','Mo','Tu','We','Th','Fr','Sa'];
    let html = days.map(d => `<div class="cal-day-label">${d}</div>`).join('');

    // Empty cells before first day
    for (let i = 0; i < first.getDay(); i++) {
      html += '<div class="cal-day empty"></div>';
    }
    for (let d = 1; d <= last.getDate(); d++) {
      const ds = `${calYear}-${String(calMonth + 1).padStart(2, '0')}-${String(d).padStart(2, '0')}`;
      const hasW = workoutDates.has(ds);
      const isToday = ds === todayStr;
      html += `<div class="cal-day${hasW ? ' has-workout' : ''}${isToday ? ' today' : ''}">${d}</div>`;
    }
    el.innerHTML = html;
  }

  function changeMonth(delta) {
    calMonth += delta;
    if (calMonth > 11) { calMonth = 0; calYear++; }
    if (calMonth < 0) { calMonth = 11; calYear--; }
    renderCalendar();
  }

  function renderWeekChart() {
    const el = document.getElementById('week-chart');
    const now = new Date();
    const weeks = [];
    for (let i = 7; i >= 0; i--) {
      const weekEnd = new Date(now);
      weekEnd.setDate(weekEnd.getDate() - i * 7);
      const weekStart = new Date(weekEnd);
      weekStart.setDate(weekStart.getDate() - 6);
      const count = workouts.filter(w => {
        const d = new Date(w.date + 'T00:00:00');
        return d >= weekStart && d <= weekEnd;
      }).length;
      const label = weekStart.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
      weeks.push({ label, count });
    }

    const max = Math.max(...weeks.map(w => w.count), 1);
    el.innerHTML = weeks.map(w => `
      <div class="bar-col">
        <div class="bar-value">${w.count || ''}</div>
        <div class="bar" style="height:${(w.count / max) * 100}%"></div>
        <div class="bar-label">${w.label}</div>
      </div>
    `).join('');
  }

  function renderPRs() {
    const el = document.getElementById('pr-list');
    const prs = {};
    workouts.forEach(w => {
      w.exercises.forEach(ex => {
        ex.sets.forEach(s => {
          const weight = Number(s.weight) || 0;
          if (weight > 0) {
            if (!prs[ex.name] || weight > prs[ex.name]) {
              prs[ex.name] = weight;
            }
          }
        });
      });
    });

    const entries = Object.entries(prs).sort((a, b) => b[1] - a[1]);
    if (entries.length === 0) {
      el.innerHTML = '<div style="text-align:center;padding:20px;color:var(--text-dim);">No weight data yet</div>';
      return;
    }
    el.innerHTML = entries.map(([name, weight]) => `
      <div class="pr-item">
        <span class="pr-exercise">${name}</span>
        <span class="pr-weight">${weight} lbs</span>
      </div>
    `).join('');
  }

  // ─── TIMER ─────────────────────────
  let timerSeconds = 90;
  let timerRemaining = 90;
  let timerInterval = null;
  let timerRunning = false;

  function setTimer(secs) {
    timerSeconds = secs;
    timerRemaining = secs;
    timerRunning = false;
    if (timerInterval) clearInterval(timerInterval);
    timerInterval = null;
    document.getElementById('timer-start').textContent = '▶ Start';
    renderTimer();
    document.querySelectorAll('.timer-preset').forEach(b => {
      b.classList.toggle('active', parseInt(b.textContent.split(':')[0]) * 60 + parseInt(b.textContent.split(':')[1]) === secs);
    });
  }

  function toggleTimer() {
    if (timerRunning) {
      clearInterval(timerInterval);
      timerRunning = false;
      document.getElementById('timer-start').textContent = '▶ Resume';
    } else {
      timerRunning = true;
      document.getElementById('timer-start').textContent = '⏸ Pause';
      timerInterval = setInterval(() => {
        timerRemaining--;
        if (timerRemaining <= 0) {
          timerRemaining = 0;
          clearInterval(timerInterval);
          timerRunning = false;
          document.getElementById('timer-start').textContent = '▶ Start';
          // Play sound
          try {
            const ctx = new (window.AudioContext || window.webkitAudioContext)();
            [0, 0.2, 0.4].forEach(t => {
              const osc = ctx.createOscillator();
              const gain = ctx.createGain();
              osc.connect(gain);
              gain.connect(ctx.destination);
              osc.frequency.value = 880;
              gain.gain.value = 0.3;
              osc.start(ctx.currentTime + t);
              osc.stop(ctx.currentTime + t + 0.15);
            });
          } catch(e) {}
          showToast('⏱️ Rest time is up!');
        }
        renderTimer();
      }, 1000);
    }
  }

  function resetTimer() {
    timerRemaining = timerSeconds;
    timerRunning = false;
    if (timerInterval) clearInterval(timerInterval);
    timerInterval = null;
    document.getElementById('timer-start').textContent = '▶ Start';
    renderTimer();
  }

  function renderTimer() {
    const m = Math.floor(timerRemaining / 60);
    const s = timerRemaining % 60;
    document.getElementById('timer-time').textContent = `${m}:${String(s).padStart(2, '0')}`;
  }

  // ─── 1RM CALCULATOR ───────────────
  function calc1RM() {
    const w = Number(document.getElementById('orm-weight').value);
    const r = Number(document.getElementById('orm-reps').value);
    const el = document.getElementById('orm-result');
    if (!w || !r || r < 1) {
      el.innerHTML = 'Enter weight and reps to estimate your one-rep max';
      el.style.color = 'var(--text-dim)';
      return;
    }
    // Epley formula
    const orm = r === 1 ? w : Math.round(w * (1 + r / 30));
    el.innerHTML = `
      <div style="font-size:2rem;font-weight:800;background:linear-gradient(135deg,var(--accent-light),var(--orange));-webkit-background-clip:text;-webkit-text-fill-color:transparent;">
        ${orm} lbs
      </div>
      <div style="margin-top:6px;font-size:0.8rem;">Estimated 1-Rep Max (Epley)</div>
      <div style="margin-top:10px;font-size:0.8rem;color:var(--text-dim);">
        95%: ${Math.round(orm * 0.95)} &nbsp;|&nbsp; 90%: ${Math.round(orm * 0.9)} &nbsp;|&nbsp; 85%: ${Math.round(orm * 0.85)} &nbsp;|&nbsp; 80%: ${Math.round(orm * 0.8)} &nbsp;|&nbsp; 75%: ${Math.round(orm * 0.75)}
      </div>
    `;
    el.style.color = 'var(--text)';
  }

  // ─── TABS ──────────────────────────
  function switchTab(tab) {
    document.querySelectorAll('.section').forEach(s => s.classList.remove('active'));
    document.querySelectorAll('.tab-btn').forEach(t => t.classList.remove('active'));
    document.getElementById(`sec-${tab}`).classList.add('active');
    document.getElementById(`tab-${tab}`).classList.add('active');

    if (tab === 'history') renderHistory();
    if (tab === 'stats') renderStats();
  }

  // ─── TOAST ─────────────────────────
  function showToast(msg) {
    const el = document.getElementById('toast');
    el.textContent = msg;
    el.classList.add('show');
    setTimeout(() => el.classList.remove('show'), 2500);
  }

  // ─── INIT RENDER ───────────────────
  renderTimer();
</script>
</body>
</html>
```

## Features

| Tab | What it does |
|---|---|
| **🏋️ Log** | Create workouts with name, date, muscle groups, and multiple exercises with sets/reps/weight. Quick-add buttons suggest exercises based on selected muscle groups. |
| **📋 History** | Searchable workout history with total volume, edit/duplicate/delete actions. "Repeat" pre-fills a template for the same workout. |
| **📊 Stats** | Overview cards (total, this week, this month, streak 🔥), interactive calendar heatmap, weekly bar chart, and Personal Records leaderboard. |
| **⏱️ Timer** | Rest timer with presets (30s–5min), audio alert on completion, and a 1RM calculator with percentage breakdowns. |

**All data persists in `localStorage`** — no account or server needed. Just open the file in any browser and start tracking!
